<!-- Interactive Logic Engine -->
<script>
    // Toast Feedback
    function showToast(message, icon = 'check_circle') {
      const toast = document.getElementById('toastNotification');
      const msgElem = document.getElementById('toastMessage');
      const iconElem = document.getElementById('toastIcon');
      if (!toast || !msgElem) return;

      msgElem.textContent = message;
      if (iconElem) iconElem.textContent = icon;

      toast.classList.remove('opacity-0', 'pointer-events-none', 'translate-y-4');
      toast.classList.add('opacity-100', 'translate-y-0');

      clearTimeout(window.__toastTimeout);
      window.__toastTimeout = setTimeout(() => {
        toast.classList.add('opacity-0', 'pointer-events-none', 'translate-y-4');
        toast.classList.remove('opacity-100', 'translate-y-0');
      }, 3400);
    }

    // Wishlist Toggle
    function toggleWishlist(btn, destinationName) {
      const icon = btn.querySelector('.material-symbols-outlined');
      const isSaved = icon.textContent === 'favorite';

      if (isSaved) {
        icon.textContent = 'favorite_border';
        icon.style.fontVariationSettings = "'FILL' 0";
        btn.classList.remove('text-error');
        btn.classList.add('text-secondary');
        showToast('Removed ' + destinationName + ' from favorites', 'favorite_border');
      } else {
        icon.textContent = 'favorite';
        icon.style.fontVariationSettings = "'FILL' 1";
        btn.classList.remove('text-secondary');
        btn.classList.add('text-error');
        showToast('Saved ' + destinationName + ' to your favorites!', 'favorite');
      }
    }

    // Destinations Carousel Scroll
    function scrollDestinations(direction) {
      const track = document.getElementById('destinationsCarouselTrack');
      if (!track) return;
      const scrollAmount = 390;
      track.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
    }

    // Filter Destination Category
    function filterCategory(btn, category) {
      document.querySelectorAll('.dest-filter-chip').forEach(b => {
        b.classList.remove('bg-primary', 'text-on-primary');
        b.classList.add('bg-surface-container-lowest', 'text-secondary');
      });
      btn.classList.remove('bg-surface-container-lowest', 'text-secondary');
      btn.classList.add('bg-primary', 'text-on-primary');

      const cards = document.querySelectorAll('.dest-card');
      cards.forEach(card => {
        if (category === 'all' || card.dataset.category === category) {
          card.classList.remove('hidden');
        } else {
          card.classList.add('hidden');
        }
      });
    }

    // Stepper Form Engine
    let currentStep = 1;
    let guestCount = 2;

    function setBookingStep(step) {
      currentStep = step;
      [1, 2, 3].forEach(s => {
        const panel = document.getElementById('stepPanel' + s);
        const tab = document.getElementById('stepTab' + s);
        if (panel) {
          if (s === step) panel.classList.remove('hidden');
          else panel.classList.add('hidden');
        }
        if (tab) {
          if (s === step) {
            tab.className = 'flex-1 py-space-xs px-2 md:px-space-md rounded-full font-label-md text-label-md transition-all flex items-center justify-center gap-2 bg-primary text-on-primary shadow-sm';
            tab.querySelector('span:first-child').className = 'w-6 h-6 rounded-full bg-surface-container-lowest text-primary text-center leading-6 font-bold text-xs';
          } else {
            tab.className = 'flex-1 py-space-xs px-2 md:px-space-md rounded-full font-label-md text-label-md transition-all flex items-center justify-center gap-2 text-secondary hover:text-primary';
            tab.querySelector('span:first-child').className = 'w-6 h-6 rounded-full bg-surface-container-high text-primary text-center leading-6 font-bold text-xs';
          }
        }
      });
      updateSummary();
    }

    function adjustGuests(delta) {
      guestCount = Math.max(1, Math.min(16, guestCount + delta));
      const display = document.getElementById('guestCountDisplay');
      const input = document.getElementById('travelersCount');
      if (display) display.textContent = guestCount + (guestCount === 1 ? ' Person' : ' Persons');
      if (input) input.value = guestCount;
      updateSummary();
    }

    function selectTier(btn, tier) {
      document.querySelectorAll('.tier-btn').forEach(b => {
        b.className = 'tier-btn py-2.5 px-3 rounded-full text-center font-label-md text-label-md bg-surface-container-low text-secondary hover:text-primary transition-all';
      });
      btn.className = 'tier-btn py-2.5 px-3 rounded-full text-center font-label-md text-label-md bg-primary text-on-primary transition-all';
      btn.dataset.tier = tier;
      updateSummary();
    }

    function updateSummary() {
      const select = document.getElementById('stepDestSelect');
      if (!select) return;

      const selectedOption = select.options[select.selectedIndex];
      const basePrice = parseInt(selectedOption.getAttribute('data-price') || '4500', 10);
      const destName = selectedOption.text.split('(')[0].trim();

      // Check addons
      let addonCost = 0;
      document.querySelectorAll('input[name="addons[]"]:checked').forEach(box => {
        if (box.value === 'van') addonCost += 1800;
        if (box.value === 'gear') addonCost += (650 * guestCount);
        if (box.value === 'guide') addonCost += 2500;
      });

      const total = (basePrice * guestCount) + addonCost;

      const summaryDest = document.getElementById('summaryDest');
      const summaryGuests = document.getElementById('summaryGuests');
      const summaryTotal = document.getElementById('summaryTotal');

      if (summaryDest) summaryDest.textContent = destName;
      if (summaryGuests) summaryGuests.textContent = guestCount + (guestCount === 1 ? ' Traveler' : ' Travelers');
      if (summaryTotal) summaryTotal.textContent = '₱' + total.toLocaleString();
    }

    function handleInlineSubmit(e) {
      e.preventDefault();
      document.getElementById('stepPanel1')?.classList.add('hidden');
      document.getElementById('stepPanel2')?.classList.add('hidden');
      document.getElementById('stepPanel3')?.classList.add('hidden');
      document.getElementById('bookingSuccessBox')?.classList.remove('hidden');
      showToast('Booking successfully recorded! Details sent to inbox.');
    }

    function resetBookingForm() {
      document.getElementById('bookingSuccessBox')?.classList.add('hidden');
      document.getElementById('inlineBookingForm')?.reset();
      guestCount = 2;
      setBookingStep(1);
    }

    // Detail Modal Handlers
    function openDetailModal(title, region, price, rating, imgSrc, desc) {
      const modal = document.getElementById('destinationDetailModal');
      if (!modal) return;

      document.getElementById('modalDetailTitle').textContent = title;
      document.getElementById('modalDetailRegion').textContent = region;
      document.getElementById('modalDetailPrice').textContent = price;
      document.getElementById('modalDetailRating').textContent = rating;
      document.getElementById('modalDetailDescription').textContent = desc;

      const img = document.getElementById('modalDetailImage');
      if (img) img.src = imgSrc;

      const bookBtn = document.getElementById('modalBookNowBtn');
      if (bookBtn) {
        bookBtn.onclick = function() {
          closeDetailModal();
          openBookingModal(title);
        };
      }

      modal.classList.remove('opacity-0', 'pointer-events-none');
      modal.querySelector('div').classList.remove('scale-95');
      modal.querySelector('div').classList.add('scale-100');
    }

    function closeDetailModal() {
      const modal = document.getElementById('destinationDetailModal');
      if (!modal) return;
      modal.classList.add('opacity-0', 'pointer-events-none');
      modal.querySelector('div').classList.remove('scale-100');
      modal.querySelector('div').classList.add('scale-95');
    }

    // Quick Booking Modal Handlers
    function openBookingModal(defaultDest = '') {
      const modal = document.getElementById('quickBookingModal');
      const input = document.getElementById('quickDestInput');
      if (!modal) return;
      if (input && defaultDest) input.value = defaultDest;

      modal.classList.remove('opacity-0', 'pointer-events-none');
      modal.querySelector('div').classList.remove('scale-95');
      modal.querySelector('div').classList.add('scale-100');
    }

    function closeBookingModal() {
      const modal = document.getElementById('quickBookingModal');
      if (!modal) return;
      modal.classList.add('opacity-0', 'pointer-events-none');
      modal.querySelector('div').classList.remove('scale-100');
      modal.querySelector('div').classList.add('scale-95');
    }

    function handleQuickBooking(e) {
      e.preventDefault();
      closeBookingModal();
      showToast('Reservation inquiry registered! Concierge will confirm.');
    }

    // FAQ Accordion
    function toggleFaq(btn) {
      const answer = btn.nextElementSibling;
      const icon = btn.querySelector('.faq-icon');
      const isHidden = answer.classList.contains('hidden');

      // Close open ones
      document.querySelectorAll('.faq-answer').forEach(a => a.classList.add('hidden'));
      document.querySelectorAll('.faq-icon').forEach(i => i.classList.remove('rotate-180'));

      if (isHidden) {
        answer.classList.remove('hidden');
        if (icon) icon.classList.add('rotate-180');
      }
    }

    // Testimonial cycling (simple visual feedback)
    function cycleTestimonial(dir) {
      showToast('Viewing guest verified review stories');
    }

    // Escape Key Listener for Modals
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeDetailModal();
        closeBookingModal();
      }
    });

    // Initialize values on load
    document.addEventListener('DOMContentLoaded', () => {
      updateSummary();
    });
  </script>
